import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static int timeRequiredToBuy(List<Integer> tickets, int k) {
        int time = 0;
        // Process until person k finishes
        while (tickets.get(k) > 0) {
            // Simulate each person in the queue
            for (int i = 0; i < tickets.size(); i++) {
                if (tickets.get(i) > 0) {
                    tickets.set(i, tickets.get(i) - 1);
                    time++;
                    // If person k is done, return immediately
                    if (i == k && tickets.get(k) == 0) {
                        return time;
                    }
                }
            }
        }
        return time;
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> tickets = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        int k = Integer.parseInt(scanner.nextLine());
        scanner.close();
        int res = timeRequiredToBuy(tickets, k);
        System.out.println(res);
    }
}
